class AhoCorasick {
  constructor(patterns) {
    this.goto = [{}];
    this.fail = [0];
    this.output = [[]];
    for (const p of patterns) this._add(p);
    this._build();
  }
  _add(word) {
    let node = 0;
    for (const c of word) {
      if (this.goto[node][c] === undefined) {
        this.goto.push({});
        this.fail.push(0);
        this.output.push([]);
        this.goto[node][c] = this.goto.length - 1;
      }
      node = this.goto[node][c];
    }
    this.output[node].push(word);
  }
  _build() {
    const queue = [];
    for (const c in this.goto[0]) queue.push(this.goto[0][c]);
    while (queue.length) {
      const node = queue.shift();
      for (const c in this.goto[node]) {
        const next = this.goto[node][c];
        queue.push(next);
        let f = this.fail[node];
        while (f && this.goto[f][c] === undefined) f = this.fail[f];
        this.fail[next] = (this.goto[f][c] !== undefined && this.goto[f][c] !== next) ? this.goto[f][c] : 0;
        this.output[next] = this.output[next].concat(this.output[this.fail[next]]);
      }
    }
  }
  search(text) {
    let node = 0;
    const results = [];
    for (let i = 0; i < text.length; i++) {
      const c = text[i];
      while (node && this.goto[node][c] === undefined) node = this.fail[node];
      node = this.goto[node][c] !== undefined ? this.goto[node][c] : 0;
      for (const word of this.output[node]) results.push([i - word.length + 1, word]);
    }
    return results;
  }
}

